{"files":[{"path":"src/views/records/dateRules.js","content":"/** 两个录入入口共用日历日期校验，错误代码用于表单和导入行提示。 */
export function validateSurveyDate(value, today) {
  if (typeof value !== 'string' || !/^\d{4}-\d{2}-\d{2}$/.test(value)) return 'INVALID_DATE';
  const parsed = new Date(`${value}T00:00:00.000Z`);
  if (Number.isNaN(parsed.valueOf()) || parsed.toISOString().slice(0, 10) !== value) return 'INVALID_DATE';
  const todayValue = today === undefined
    ? new Date().toLocaleDateString('en-CA')
    : today;
  if (typeof todayValue !== 'string' || !/^\d{4}-\d{2}-\d{2}$/.test(todayValue)) return 'INVALID_DATE';
  const todayParsed = new Date(`${todayValue}T00:00:00.000Z`);
  if (Number.isNaN(todayParsed.valueOf()) || todayParsed.toISOString().slice(0, 10) !== todayValue) return 'INVALID_DATE';
  if (value > todayValue) return 'FUTURE_DATE';
  return null;
}
"},{"path":"src/views/records/create.js","content":"import { validateSurveyDate } from './dateRules.js';

/** 新增失败返回字段错误；成功时保留调用者给出的其他字段。 */
export function createSurvey(input, today) {
  const error = validateSurveyDate(input.surveyDate, today);
  return error ? { ok: false, fieldErrors: { surveyDate: error } }
    : { ok: true, record: { ...input } };
}
"},{"path":"src/views/records/import.js","content":"import { validateSurveyDate } from './dateRules.js';

/** 导入保持按行部分成功；无效日期只影响所属行，不改变其他记录。 */
export function importSurveys(rows, today) {
  const inserted = [];
  const errors = [];
  rows.forEach((record, index) => {
    const code = validateSurveyDate(record.surveyDate, today);
    if (code) errors.push({ row: index + 1, field: 'surveyDate', code });
    else inserted.push({ ...record });
  });
  return { inserted, errors };
}
"}],"summary":"在共用 validateSurveyDate 中增加未来日期限制：传入 today 时以其为基准，未传入时使用系统本地当日日历日期，超过今天返回 FUTURE_DATE；新增和导入入口沿用该共用校验。"}
